@Test
	public void cas22() throws ParsingException{
		String name = CASTools.uninvertCASName("L-Alanine, N-carboxy-, 1-ethyl ester", parseRules);
		assertEquals("1-ethyl N-carboxy-L-Alaninate", name);
	}

